      // declaration files are exempt.
      files: ["**/*.ts", "**/*.tsx", "**/*.mts", "**/*.cts"],
      excludeFiles: [
        "**/*.test.ts",
        "**/*.test.tsx",
        "**/*.test.mts",
        "**/*.test.cts",
