     let settled = false;
     const promptFn: PromptFn = () => new Promise(() => {});
     void runWithBreaker("hi", { profiles: [PROFILES[0]], breaker: breaker(), promptFn }).finally(
       () => {
         settled = true;
       },
     );
     await new Promise((r) => setTimeout(r, 10));
     expect(settled).toBe(false);
   });
 });

