  restoreGeneratedMarkdown,
  scopeGeneratedMarkdown,
  type GeneratedMarkdown,
} from "./generated-values.ts";

/**
 * Pull the first `{…}` JSON object out of a model response, tolerating surrounding prose or code
 * fences. Returns `null` when no valid object is found.
 */
export function extractJsonObject(raw: string): Record<string, unknown> | null {
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start === -1 || end <= start) return null;
  try {
    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
    return typeof parsed === "object" && parsed !== null
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

/** Build the shared JSON-batch translation prompt used by AI-backed adapters. */
export function buildBatchTranslationPrompt(
  targetLanguage: string,
  payload: Readonly<Record<string, string>>,
): string {
  const template = readFileSync(
    new URL("../prompts/batch-translation.prompt.md", import.meta.url),
    "utf8",
  );
  return template
