      "ui:translate:agy": {
        command: "vp run @pantoken/web-components#translate:agy",
        cache: false,
      },
      "ui:translate:copilot": {
        command: "vp run @pantoken/web-components#translate:copilot",
        cache: false,
      },
      "ui:translate:force": {
        command: "vp run @pantoken/web-components#translate:force",
        cache: false,
      },
      "ui:translate:force:agy": {
        command: "vp run @pantoken/web-components#translate:force:agy",
        cache: false,
      },
      "ui:translate:force:copilot": {
        command: "vp run @pantoken/web-components#translate:force:copilot",
        cache: false,
      },
      // TinyMCE string localization.
      "tinymce:translate": {
        command: "vp run @pantoken/tinymce#translate",
        cache: false,
      },
      "tinymce:translate:agy": {
        command: "vp run @pantoken/tinymce#translate:agy",
        cache: false,
      },
      "tinymce:translate:copilot": {
        command: "vp run @pantoken/tinymce#translate:copilot",
        cache: false,
      },
      "tinymce:translate:force": {
        command: "vp run @pantoken/tinymce#translate:force",
        cache: false,
      },
      "tinymce:translate:force:agy": {
        command: "vp run @pantoken/tinymce#translate:force:agy",
        cache: false,
      },
      "tinymce:translate:force:copilot": {
        command: "vp run @pantoken/tinymce#translate:force:copilot",
        cache: false,
      },
      // Layouts (plugins/pantoken/layouts) string localization.
      "layouts:translate": {
        command: "vp run @pantoken/plugin-layouts#translate",
        cache: false,
      },
      "layouts:translate:agy": {
        command: "vp run @pantoken/plugin-layouts#translate:agy",
        cache: false,
      },
      "layouts:translate:copilot": {
        command: "vp run @pantoken/plugin-layouts#translate:copilot",
        cache: false,
      },
      "layouts:translate:force": {
        command: "vp run @pantoken/plugin-layouts#translate:force",
        cache: false,
      },
      "layouts:translate:force:agy": {
        command: "vp run @pantoken/plugin-layouts#translate:force:agy",
        cache: false,
      },
      "layouts:translate:force:copilot": {
        command: "vp run @pantoken/plugin-layouts#translate:force:copilot",
        cache: false,
      },
      // Docs locale translation (both claude and agy variants).
      "docs:translate": {
        command: "vp run @pantoken/docs#docs:locales:translate",
        cache: false,
      },
      "docs:translate:agy": {
        command: "vp run @pantoken/docs#docs:locales:translate:agy",
        cache: false,
      },
      "docs:translate:copilot": {
        command: "vp run @pantoken/docs#docs:locales:translate:copilot",
        cache: false,
      },
      "docs:translate:force": {
        command: "vp run @pantoken/docs#docs:locales:translate:force",
        cache: false,
      },
      "docs:translate:force:agy": {
        command: "vp run @pantoken/docs#docs:locales:translate:agy:force",
        cache: false,
      },
      "docs:translate:force:copilot": {
        command: "vp run @pantoken/docs#docs:locales:translate:copilot:force",
        cache: false,
      },
      // CLI (scaffold and ai) string localization.
      "cli:translate": {
        command: "vp run @pantoken/scaffold#translate && vp run @pantoken/ai#translate",
        cache: false,
      },
      "cli:translate:agy": {
        command: "vp run @pantoken/scaffold#translate:agy && vp run @pantoken/ai#translate:agy",
        cache: false,
      },
      "cli:translate:copilot": {
        command:
          "vp run @pantoken/scaffold#translate:copilot && vp run @pantoken/ai#translate:copilot",
        cache: false,
      },
      "cli:translate:force": {
        command: "vp run @pantoken/scaffold#translate:force && vp run @pantoken/ai#translate:force",
        cache: false,
      },
      "cli:translate:force:agy": {
        command:
          "vp run @pantoken/scaffold#translate:force:agy && vp run @pantoken/ai#translate:force:agy",
        cache: false,
      },
      "cli:translate:force:copilot": {
        command:
          "vp run @pantoken/scaffold#translate:force:copilot && vp run @pantoken/ai#translate:force:copilot",
        cache: false,
      },
      // Umbrella tasks for all translation domains.
      "i18n:translate": {
        command: "true",
        dependsOn: [
          "ui:translate",
          "tinymce:translate",
          "layouts:translate",
          "docs:translate",
          "cli:translate",
        ],
        cache: false,
      },
      "i18n:translate:agy": {
        command: "true",
        dependsOn: [
          "ui:translate:agy",
          "tinymce:translate:agy",
          "layouts:translate:agy",
          "docs:translate:agy",
          "cli:translate:agy",
        ],
        cache: false,
      },
      "i18n:translate:copilot": {
        command: "true",
        dependsOn: [
          "ui:translate:copilot",
          "tinymce:translate:copilot",
          "layouts:translate:copilot",
          "docs:translate:copilot",
          "cli:translate:copilot",
        ],
        cache: false,
      },
      // Bypasses every domain's translation-memory cache — retranslates and overwrites everything,
      // even already-cached content. Use after fixing an adapter bug or a bad translation; see
      // DOCS_TRANSLATION_FORCE / I18N_TRANSLATION_FORCE in the respective translation pipelines.
      "i18n:translate:force": {
        command: "true",
        dependsOn: [
          "ui:translate:force",
          "tinymce:translate:force",
          "layouts:translate:force",
          "docs:translate:force",
          "cli:translate:force",
        ],
        cache: false,
      },
      // Same as i18n:translate:force but routed through the agy adapter wrapper.
      "i18n:translate:force:agy": {
        command: "true",
        dependsOn: [
          "ui:translate:force:agy",
          "tinymce:translate:force:agy",
          "layouts:translate:force:agy",
          "docs:translate:force:agy",
          "cli:translate:force:agy",
        ],
        cache: false,
      },
      // Same as i18n:translate:force but routed through the copilot adapter wrapper.
      "i18n:translate:force:copilot": {
        command: "true",
        dependsOn: [
          "ui:translate:force:copilot",
          "tinymce:translate:force:copilot",
          "layouts:translate:force:copilot",
          "docs:translate:force:copilot",
          "cli:translate:force:copilot",
        ],
        cache: false,
      },
      // CI-safe drift checks for the UI and CLI i18n domains. Every configured translation gap is
      // blocking now that the locale catalogs are complete. Docs drift needs the generated EN API
      // tree and is included in the all-surface task below.
      "i18n:check:drift": {
        command:
          "vp run @pantoken/translation-adapters#build && vp run @pantoken/i18n-engine#build && vp run @pantoken/web-components#check:drift && vp run @pantoken/tinymce#check:drift && vp run @pantoken/plugin-layouts#check:drift && vp run @pantoken/scaffold#check:drift && vp run @pantoken/ai#check:drift",
      },
      "i18n:drift:fix": {
        command: "node scripts/i18n-drift-fix.ts --provider claude",
        dependsOn: ["@pantoken/translation-adapters#build", "@pantoken/i18n-engine#build"],
        cache: false,
      },
      "i18n:drift:fix:agy": {
        command: "node scripts/i18n-drift-fix.ts --provider agy",
        dependsOn: ["@pantoken/translation-adapters#build", "@pantoken/i18n-engine#build"],
        cache: false,
      },
      "i18n:drift:fix:copilot": {
        command: "node scripts/i18n-drift-fix.ts --provider copilot",
        dependsOn: ["@pantoken/translation-adapters#build", "@pantoken/i18n-engine#build"],
        cache: false,
      },
      // Generate the local, git-ignored language coverage report. Keep this uncached so the report
      // always reflects the current PO catalogs and policy configuration.
      "i18n:coverage": {
        command:
          "vp run @pantoken/i18n-engine#build && node tools/i18n-engine/bin/i18n.mjs --config i18n.config.json stats --html",
        cache: false,
      },
      // Keep the local HTML coverage dashboard synchronized while translation jobs update catalogs.
      "i18n:coverage:watch": {
        command:
          "vp run @pantoken/i18n-engine#build && node tools/i18n-engine/bin/i18n.mjs --config i18n.config.json stats --html --watch",
        cache: false,
      },
      // Every read-only catalog-backed i18n surface at once, including docs translations. The docs
      // check uses an existing generated API tree when one is present; it must not regenerate the
      // tree or rewrite `l10n/docs.api.pot`. Structural locale parity remains part of the docs build,
      // which already generates all locale trees before checking them.
      "i18n:check:drift:all": {
        command:
          "node tools/i18n-engine/bin/i18n.mjs --config i18n.config.json lint && vp run i18n:check:drift && vp run @pantoken/docs#docs:check:drift",
        cache: false,
      },
      // Backward-compatible alias for the complete blocking drift sweep.
      "i18n:check:drift:strict": {
        command: "I18N_DRIFT_STRICT=1 vp run i18n:check:drift:all",
        cache: false,
      },
      // Publishing validates the complete English API tree; TypeDoc alone does not include CSS API
      // pages, so CSS generation must finish before the drift check refreshes its source catalog.
      "gate:i18n": {
        command:
          "vp run @pantoken/docs#docs:api:en:build && vp run @pantoken/docs#docs:api:css && vp run i18n:check:drift:all",
        dependsOn: ["build:all"],
      },
      "i18n:bundles:build": {
        command: "vp run @pantoken/web-components#generate",
        dependsOn: ["build:all"],
      },
      "changeset:add": {
        command: "vpx changeset",
        cache: false,
      },
      "release:status": {
        command: "vpx changeset status --verbose",
      },
      "release:coverage": {
        command: "node scripts/release/check-changeset-coverage.ts",
      },
      // Driven by the changesets action (.github/workflows/release.yml): `version` opens/updates the
      // Version Packages PR, `publish` ships it via the npm CLI (not `changeset publish`, which shells out
      // to pnpm, whose OIDC token exchange is broken). The script prints `New tag:` lines the action turns
      // into git tags + GitHub releases. See scripts/release/publish-npm.ts. NOTE: CI runs the publish
      // script with plain `node`, NOT `vp run release:publish` — the `vp run` launcher scrubs the
      // `ACTIONS_ID_TOKEN_REQUEST_*` env vars npm needs for OIDC. This task stays for local/manual runs.
      // Bump versions AND refresh the fallow regression baseline so each release re-bases the floor
      // (the changesets action commits both into the Version PR). fallow runs as a direct bin — never
      // a nested `vp` — and `|| true` keeps its non-zero "findings present" exit from failing the
      // version step; it still writes fallow-baseline.json. fallow writes that JSON unformatted, and
      // changesets can emit changelog lines with trailing whitespace, so `vp fmt` both afterwards —
      // otherwise the Version PR can fail the `vp check` format gate on generated files.
      // Assumes build already ran (release.yml).
      "release:version": {
        command:
          'vpx changeset version && (node_modules/.bin/fallow dead-code --save-regression-baseline fallow-baseline.json || true) && vp fmt "**/CHANGELOG.md" fallow-baseline.json',
      },
      "release:publish": {
        command: "node scripts/release/publish-npm.ts",
      },
      "release:pre:enter": {
        command: "vpx changeset pre enter next",
      },
      "release:pre:exit": {
        command: "vpx changeset pre exit",
      },
      // The publish gate. `check:publish` → `gate:publish`, which fans out the three publish-correctness
      // checks: repository metadata (needed for npm OIDC provenance — a missing `repository.url` silently
      // breaks it), publint, and attw. publint/attw pack each package, so they wait on `build:all`;
      // `gate:repository` is a pure manifest read with no build dependency.
      "gate:repository": {
        command: "node scripts/release/check-repository-metadata.ts",
      },
      // Writer counterpart to `gate:repository`: stamps the canonical npm metadata onto every
      // publishable package.json. Run after adding a package; the gate then keeps it correct.
      "sync:repository": {
        command: "node scripts/release/sync-repository-metadata.ts",
      },
      "gate:publint": {
        command:
          'vp exec -F "./packages/**" -F "./formats/**" -F "./platforms/**" -F "./renderers/**" -F "./bundlers/**" -F "./design/**" -F "./ai/**" -F "./plugins/**" -F "./tools/**" publint',
        dependsOn: ["build:all"],
      },
      "gate:attw": {
        command:
          'vp exec -F "./packages/**" -F "./formats/**" -F "./platforms/**" -F "./renderers/**" -F "./bundlers/**" -F "./design/**" -F "./ai/**" -F "./plugins/**" -F "./tools/**" attw --pack --profile strict --no-emoji --ignore-rules no-resolution cjs-resolves-to-esm',
        dependsOn: ["build:all"],
      },
      "gate:publish": {
        command: "true",
        dependsOn: ["gate:repository", "gate:publint", "gate:attw", "gate:i18n"],
      },
      // Root convenience alias so `vp run scaffold:dev <platform>` works from anywhere in the repo;
      // args pass through to the underlying package task. See packages/scaffold/scripts/scaffold-dev.ts.
      "scaffold:dev": {
        command: "vp run @pantoken/scaffold#scaffold:dev",
        cache: false,
      },
    },
  },
});

